  const chip = (v, label, title) => `<button type="button" data-op="voice" data-v="${v}" data-i="${i}" data-w="${where}" class="${(pref || '') === v ? 'on' : !pref && v === eff ? 'eff' : ''}" title="${esc(title)}">${label}</button>`;
