function evolutionWorld(pkm){const st=latestState()?.state||{};return {time:String(st.时间||pkm?.world?.time||''),location:String(st.地点||pkm?.world?.location||''),weather:String(st.天气||st.weather||pkm?.world?.weather||'')};}
