    if (/麻痹/.test(status)) { anim('shake', 500); burst(STAR, 3, 'yl'); say('（身体一抽一抽的，麻痹了……）'); return; }
    if (/灼伤/.test(status)) { anim('shake', 500); burst(STAR, 3, 'rd'); say('（被烫伤的地方还在疼……）'); return; }
